from mk import *
STRICT["on"] = True
import math

def fig():
    g = Fig(560, 200, "שני גופים במסה 1 קילוגרם כל אחד, מחוברים בקפיץ מכווץ, מחליקים על משטח חלק. אחרי שחרור הקפיץ אחד נע בכיוון x ב-3 מטר לשנייה והשני בכיוון y ב-4 מטר לשנייה")
    g.add('<line x1="60" y1="170" x2="250" y2="170" stroke="var(--d-line)" stroke-width="1.6" marker-end="url(#f-axis)"/>'); g.add('<line x1="60" y1="170" x2="60" y2="20" stroke="var(--d-line)" stroke-width="1.6" marker-end="url(#f-axis)"/>')
    g.text(256, 174, "x", anchor="start"); g.text(66, 26, "y", anchor="start")
    g.block(110, 120, 30, 30, "m"); g.spring(125, 120, 165, 120, coils=4); g.block(180, 120, 30, 30, "m")
    g.arrow(205, 90, 245, 60, "v₀ ?", lx=250, ly=58, anchor="start")
    g.block(380, 150, 30, 30, "m"); g.arrow(397, 150, 457, 150, "3 m/s", lx=430, ly=140)
    g.block(330, 110, 30, 30, "m"); g.arrow(330, 93, 330, 33, "4 m/s", lx=340, ly=60, anchor="start")
    g.heb(150, 196, "לפני"); g.heb(400, 196, "אחרי")
    return g

v2 = math.sqrt(25 / 0.3)
E(id="bagrut-1980r-q2", year=1980, label="1980 שאלה 2 (רחובות)", topic="momentum", sub="mom-conservation", diff=3, fig=fig,
  stem=r"שני גופים שווים, כל אחד במסה $m = 1\,\text{kg}$, מחוברים בקפיץ מכווץ וקל, ומחליקים בלי חיכוך על משטח אופקי. ברגע מסוים הקפיץ משתחרר, והגופים נפרדים ממנו. גוף אחד נע בכיוון $x$ במהירות $v_x = 3\,\text{m/s}$, והגוף השני נע בכיוון $y$, שניצב ל-$x$, במהירות $v_y = 4\,\text{m/s}$.",
  parts=[
    P("א", r"מה הייתה המהירות המשותפת $\vec v_0$ של שני הגופים לפני שהקפיץ השתחרר: מה הגודל שלה, ומה הזווית בינה לבין ציר $x$?", multi((r"הגודל", 2.5, "m/s"), (r"הזווית עם ציר x", math.degrees(math.atan(2 / 1.5)), "°")), ["principle", "algebra"], [
        X(r"על המשטח אין כוחות חיצוניים אופקיים: הקפיץ פנימי. לכן התנע הכולל נשמר, בכל ציר בנפרד. הכיוונים החיוביים הם הכיוונים של הצירים."),
        S(r"שימור תנע", r"התנע הכולל לפני השחרור שווה לתנע הכולל אחריו", r"2m\,\vec v_0 = m\,(3,\ 0) + m\,(0,\ 4)", eq=r"m_A\vec v_A + m_B\vec v_B = m_A\vec u_A + m_B\vec u_B"),
        S(r"מחלקים בפעמיים המסה", r"כך מקבלים את רכיבי המהירות המשותפת", r"\vec v_0 = (1.5,\ 2)\,\text{m/s}"),
        S(r"הגודל", r"לפי משפט פיתגורס", r"v_0 = \sqrt{1.5^2 + 2^2} = 2.5\,\text{m/s}"),
        S(r"הזווית", r"הטנגנס של הזווית הוא הרכיב בציר y חלקי הרכיב בציר x", r"\tan\theta = \frac{2}{1.5} \;\Rightarrow\; \theta \approx 53^\circ"),
    ], r"$2.5\,\text{m/s}$, בזווית $\approx 53^\circ$ לציר $x$", key=r"2.5 m/s ; ≈53°"),
    P("ב", r"כמה אנרגיה הייתה אגורה בקפיץ המכווץ?", num(6.25, "J"), ["principle"], [
        S(r"האנרגיה הקינטית לפני", r"שני הגופים יחד, במהירות המשותפת", r"E_0 = \tfrac{1}{2} \cdot 2 \cdot 2.5^2 = 6.25\,\text{J}", eq=r"E_k = \tfrac{1}{2}mv^2"),
        S(r"האנרגיה הקינטית אחרי", r"כל גוף במהירות שלו", r"E_1 = \tfrac{1}{2} \cdot 1 \cdot 3^2 + \tfrac{1}{2} \cdot 1 \cdot 4^2 = 12.5\,\text{J}"),
        S(r"האנרגיה בקפיץ", r"אין חיכוך, ולכן כל התוספת לאנרגיה הקינטית באה מהקפיץ", r"U_{sp} = 12.5 - 6.25 = 6.25\,\text{J}"),
    ], r"$6.25\,\text{J}$", key=r"6.25 J"),
    P("ג", r"מכווצים שוב את הקפיץ, הפעם פי שניים יותר מקודם. לשני הקצוות של הקפיץ המכווץ, שנמצא במנוחה, מחברים גופים שמסותיהם שונות: $m_1 = 0.1\,\text{kg}$ ו-$m_2 = 0.2\,\text{kg}$. משחררים את הקפיץ, והגופים נפרדים ממנו. מה המהירות של כל אחד מהגופים?", multi((r"המהירות של m₁", 2 * v2, "m/s"), (r"המהירות של m₂", v2, "m/s")), ["principle", "algebra"], [
        S(r"האנרגיה בקפיץ", r"האנרגיה של קפיץ פרופורציונית לריבוע הכיווץ. כיווץ כפול נותן אנרגיה פי ארבעה", r"U_{sp} = \tfrac{1}{2}K(2\Delta\ell)^2 = 4 \cdot 6.25 = 25\,\text{J}", eq=r"U_{sp} = \tfrac{1}{2}K(\Delta\ell)^2"),
        S(r"שימור תנע", r"המערכת מתחילה ממנוחה. הכיוון החיובי הוא כיוון התנועה של הגוף הראשון", r"0 = 0.1\,u_1 + 0.2\,(-u_2) \;\Rightarrow\; u_1 = 2u_2", eq=r"m_A\vec v_A + m_B\vec v_B = m_A\vec u_A + m_B\vec u_B"),
        S(r"שימור אנרגיה", r"כל האנרגיה של הקפיץ הופכת לאנרגיה קינטית של שני הגופים", r"\tfrac{1}{2} \cdot 0.1 \cdot (2u_2)^2 + \tfrac{1}{2} \cdot 0.2\,u_2^2 = 25 \;\Rightarrow\; 0.3\,u_2^2 = 25", eq=r"E_k = \tfrac{1}{2}mv^2"),
        S(r"פותרים", r"מבודדים ומוציאים שורש", r"u_2 = \sqrt{\frac{25}{0.3}} \approx 9.13\,\text{m/s},\qquad u_1 = 2u_2 \approx 18.26\,\text{m/s}"),
    ], r"$m_1$: $\approx 18.26\,\text{m/s}$. $m_2$: $\approx 9.13\,\text{m/s}$, בכיוון ההפוך", key=r"18.26 m/s ; 9.13 m/s"),
  ],
  concepts=["שימור תנע ברכיבים", "אנרגיה אגורה בקפיץ", "פיצוץ ממנוחה"],
  summary=r"שני גופים שקפיץ דוחף זה מזה: מהירות משותפת לפני, אנרגיית הקפיץ, ומהירויות כשהמסות שונות והכיווץ כפול.",
  review="הנחה שלי.\nסעיפים א ו-ג הם סעיף אחד כל אחד, כמו במקור, עם שתי תיבות.\nמה לבדוק: רק לאשר.")
